#pragma once

#include <cstdint>
#include <string>
#include <string_view>
#include <vector>

namespace KCDC::Shared::Game {
    /** One row of `Libs/Tables/dlc.xml`. Generated by `tools/generate_dlc_catalog.py`; the server has no game module to read the table from. */
    struct DLCEntry {
        /** `dlc_name`: the `E_DLC::Type` spelling, and what `server.json` names a DLC by. */
        std::string_view name;

        /** English `ui_name`; empty for the two rows without one. */
        std::string_view displayName;

        /** `dlc_id`, which is the `E_DLC::Type` value. */
        std::uint8_t id;

        /** False for the two rows with app id 0, which no account can hold. */
        bool ownable;
    };

    /** Ids run 1..11; `E_DLC::Type::Last` is 12. */
    inline constexpr std::uint8_t kMaxDLCId = 11;

    /** Id 0 is `Invalid` and owns no bit. */
    inline constexpr std::uint16_t DLCBit(std::uint8_t id) {
        return id >= 1 && id <= kMaxDLCId ? static_cast<std::uint16_t>(1U << id) : static_cast<std::uint16_t>(0);
    }

    extern const std::vector<DLCEntry> g_DLCs;

    /** Exact and case-sensitive, as the engine's own `E_DLC::FromString` is. */
    const DLCEntry *FindDLCByName(std::string_view name);

    /** "Legacy of the Forge, Mysteria Ecclesiae". */
    std::string DLCMaskToLabels(std::uint16_t mask);
} // namespace KCDC::Shared::Game
